INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM201CKB1', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'Researchers want to determine whether a new tutoring method improves standardized test scores. They randomly select $78$ students from three high schools in a suburban district and randomly assign $39$ students to the new method while $39$ students continue with the existing method. After one semester, students using the new method score significantly higher on average. A publishing company''s brochure states: "This tutoring method is proven to raise test scores for students of all ages and backgrounds nationwide." Which of the following best evaluates the brochure''s claim?', NULL, $lyceon_json$[{"key":"A","text":"The claim is supported because the study used random assignment to treatment groups."},{"key":"B","text":"The claim is supported because the score difference was statistically significant."},{"key":"C","text":"The claim overgeneralizes because all students were from suburban high schools in one district, so the results may not apply to students of different ages, backgrounds, or school settings."},{"key":"D","text":"The claim is invalid because students should have been allowed to choose which tutoring method they wanted."}]$lyceon_json$::jsonb, 'C', NULL, E'Although random assignment supports a causal conclusion within this study, all participants were high school students from three suburban schools in one district. Student demographics, school resources, prior academic preparation, and regional educational standards vary widely, so the results cannot be generalized to students of all ages and backgrounds nationwide. Additionally, the brochure claims the method is "proven," which overstates what a single study with $78$ students can establish. Citing random assignment alone or statistical significance alone as justification ignores the limitation on generalizability — both support internal validity but do not address external validity across different populations. Suggesting that students should have chosen their own method reflects a misunderstanding of experimental design: allowing self-selection would introduce confounding variables and undermine the study''s ability to establish causation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20V5O3N', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'grid_in', E'What value of $x$ satisfies the equation $19x + 38 = 247$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '11', ARRAY['11'], E'Subtracting $38$ from both sides gives $19x = 209$. Dividing both sides by $19$ yields $x = 11$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21MM5MT', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'grid_in', E'In a survey of 350 residents, $48\\%$ own a bicycle. Of those bicycle owners, $25\\%$ also own a skateboard. How many residents own both a bicycle and a skateboard?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '42', ARRAY['42'], E'First, find the number of bicycle owners: $0.48 \\times 350 = 168$. Then find how many of those also own a skateboard: $0.25 \\times 168 = 42$. A common error is computing $25\\%$ of 350 directly ($0.25 \\times 350 = 87.5$), applying the skateboard percentage to all residents rather than only to bicycle owners. Another error is adding the two percentages ($48\\% + 25\\% = 73\\%$) and computing $0.73 \\times 350 = 255.5$, which conflates the two groups.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM230A7VF', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'mcq', E'In triangle $DEF$, the exterior angle at vertex $F$ measures $136^\\circ$. If the measure of angle $D$ is three times the measure of angle $E$, what is the measure, in degrees, of angle $D$?', NULL, $lyceon_json$[{"key":"A","text":"$34^\\circ$"},{"key":"B","text":"$44^\\circ$"},{"key":"C","text":"$68^\\circ$"},{"key":"D","text":"$102^\\circ$"}]$lyceon_json$::jsonb, 'D', NULL, E'By the exterior angle theorem, the exterior angle at $F$ equals the sum of the two non-adjacent interior angles: angle $D$ + angle $E = 136^\\circ$. Since angle $D = 3 \\times$ angle $E$, substituting gives $3E + E = 136$, so $4E = 136$ and $E = 34^\\circ$. Therefore angle $D = 3(34) = 102^\\circ$. The value $34^\\circ$ is angle $E$, not angle $D$, answering the wrong angle. The value $44^\\circ$ comes from computing $180 - 136 = 44$ to find angle $F$ and then reporting that instead of angle $D$. The value $68^\\circ$ results from dividing $136$ by $2$ and assuming equal angles, ignoring the $3:1$ ratio between the two angles.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2346BF3', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'A data set consists of the values $9, 14, 22, 22, 31, 46$. What is the median of this data set?', NULL, $lyceon_json$[{"key":"A","text":"$18$"},{"key":"B","text":"$22$"},{"key":"C","text":"$24$"},{"key":"D","text":"$26.5$"}]$lyceon_json$::jsonb, 'B', NULL, E'The data set has 6 values in order: $9, 14, 22, 22, 31, 46$. The median of an even-count data set is the average of the 3rd and 4th values: $\\frac{22 + 22}{2} = 22$. The value 18 comes from averaging the 2nd and 3rd values ($\\frac{14 + 22}{2} = 18$), using incorrect positions for the middle pair. The value 24 comes from computing the mean ($\\frac{9 + 14 + 22 + 22 + 31 + 46}{6} = \\frac{144}{6} = 24$) instead of the median. The value 26.5 comes from averaging the 4th and 5th values ($\\frac{22 + 31}{2} = 26.5$), misidentifying which two values are in the middle.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23RTZP4', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A scatterplot shows the relationship between the number of practice sessions per week and a student''s typing speed in words per minute. The line of best fit has a slope of $4.3$. Which of the following is the best interpretation of this slope?', NULL, $lyceon_json$[{"key":"A","text":"For each additional practice session per week, the predicted typing speed increases by $4.3$ words per minute."},{"key":"B","text":"A student who completes $4.3$ practice sessions per week will type the fastest."},{"key":"C","text":"The typing speed is always $4.3$ times the number of practice sessions."},{"key":"D","text":"A student with no practice sessions has a predicted typing speed of $4.3$ words per minute."}]$lyceon_json$::jsonb, 'A', NULL, E'The slope of a line of best fit represents the predicted change in the dependent variable for each one-unit increase in the independent variable. A slope of $4.3$ means the predicted typing speed increases by $4.3$ words per minute for each additional practice session per week. The claim about typing fastest at $4.3$ sessions confuses the slope value with a specific threshold and misinterprets the linear model. The claim that speed is always $4.3$ times the number of sessions confuses the slope with direct proportionality, ignoring the y-intercept of the model. The claim about a baseline speed of $4.3$ words per minute confuses the slope with the y-intercept.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM246NMBC', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'A bakery sells custom cakes for $\\$19$ each plus a flat $\\$53$ delivery fee. Which function $f(c)$ gives the total cost, in dollars, for ordering $c$ cakes with delivery?', NULL, $lyceon_json$[{"key":"A","text":"$f(c) = 19c + 53$"},{"key":"B","text":"$f(c) = 19c - 53$"},{"key":"C","text":"$f(c) = 53c + 19$"},{"key":"D","text":"$f(c) = 72c$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total cost is the per-cake price times the number of cakes plus the fixed delivery fee: $f(c) = 19c + 53$. The function $19c - 53$ results from a sign error, subtracting the delivery fee instead of adding it. The function $53c + 19$ reflects a concept gap, swapping the per-cake rate and the one-time delivery fee. The function $72c$ comes from an equation setup error, adding $19$ and $53$ into a single rate and treating the entire cost as proportional to the number of cakes.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24Q2AKL', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'Line $p$ is perpendicular to the line $4x - 3y = 15$ and passes through the point $(8, -2)$. What is the $y$-intercept of line $p$?', NULL, $lyceon_json$[{"key":"A","text":"$(0, -8)$"},{"key":"B","text":"$(0, -5)$"},{"key":"C","text":"$(0, -4)$"},{"key":"D","text":"$(0, 4)$"}]$lyceon_json$::jsonb, 'D', NULL, E'Rearranging $4x - 3y = 15$ gives $y = \\frac{4}{3}x - 5$, so the slope is $\\frac{4}{3}$. A perpendicular line has slope $-\\frac{3}{4}$. Using point-slope form with $(8, -2)$: $y + 2 = -\\frac{3}{4}(x - 8)$, which gives $y + 2 = -\\frac{3}{4}x + 6$, so $y = -\\frac{3}{4}x + 4$. The $y$-intercept is $(0, 4)$. The intercept $(0, -8)$ results from an equation setup error — using the reciprocal slope $\\frac{3}{4}$ instead of the negative reciprocal $-\\frac{3}{4}$, giving $y + 2 = \\frac{3}{4}(x - 8)$, then $y = \\frac{3}{4}x - 8$. The intercept $(0, -5)$ reflects a concept gap, simply reusing the $y$-intercept of the original line without computing the new equation. The intercept $(0, -4)$ comes from a sign error — arriving at $y = -\\frac{3}{4}x - 4$ by incorrectly subtracting $2$ from $-2$ when simplifying the point-slope equation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25JMTZJ', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'grid_in', E'If $\\frac{10x^2 + 31x - 14}{2x + 7} = ax + b$ for all $x \\neq -\\frac{7}{2}$, what is the value of $a + b$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '3', ARRAY['3'], E'Factor the numerator $10x^2 + 31x - 14$. Find two numbers with product $10 \\times (-14) = -140$ and sum $31$. Those numbers are $35$ and $-4$. Rewriting: $10x^2 + 35x - 4x - 14 = 5x(2x + 7) - 2(2x + 7) = (5x - 2)(2x + 7)$. Dividing by $(2x + 7)$ gives $5x - 2$, so $a = 5$ and $b = -2$. Therefore $a + b = 5 + (-2) = 3$.', NULL, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26MZ3ER', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'The equation of a circle in the $xy$-plane is $x^2 + y^2 - 14x + 6y - 23 = 0$. What is the radius of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$\\sqrt{23}$"},{"key":"B","text":"$7$"},{"key":"C","text":"$9$"},{"key":"D","text":"$81$"}]$lyceon_json$::jsonb, 'C', NULL, E'Completing the square: $(x^2 - 14x + 49) + (y^2 + 6y + 9) = 23 + 49 + 9$, which gives $(x - 7)^2 + (y + 3)^2 = 81$. The radius is $r = \\sqrt{81} = 9$. The value $\\sqrt{23}$ comes from taking the square root of the constant $23$ in the original equation without completing the square, misreading the equation''s structure. The value $7$ confuses the $x$-coordinate of the center with the radius, likely from an error in the completing-the-square process. The value $81$ reports $r^2$ rather than $r$, failing to take the final square root when extracting the radius from standard form.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM277AI0D', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $\\frac{36x^2 - 121}{6x + 11}$ for $x \\neq -\\frac{11}{6}$?', NULL, $lyceon_json$[{"key":"A","text":"$6x + 11$"},{"key":"B","text":"$6x - 11$"},{"key":"C","text":"$36x - 121$"},{"key":"D","text":"$6x^2 - 11$"}]$lyceon_json$::jsonb, 'B', NULL, E'The numerator $36x^2 - 121$ is a difference of squares: $(6x)^2 - 11^2 = (6x + 11)(6x - 11)$. Dividing by $(6x + 11)$ cancels one factor, leaving $6x - 11$. The distractor $6x + 11$ results from a sign error — canceling the wrong factor and keeping the divisor itself. The distractor $36x - 121$ comes from dividing each term of the numerator by $6x + 11$ separately rather than factoring, which does not simplify correctly. The distractor $6x^2 - 11$ reflects a conceptual gap in the difference-of-squares identity, incorrectly taking the square root of each term individually.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27N1NZG', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'For what value of $k$ does the system $y = 4x^2 + 6x + k$ and $y = 10x - 3$ have exactly one real solution?', NULL, $lyceon_json$[{"key":"A","text":"$-5$"},{"key":"B","text":"$-3$"},{"key":"C","text":"$-2$"},{"key":"D","text":"$2$"}]$lyceon_json$::jsonb, 'C', NULL, E'Setting the equations equal: $4x^2 + 6x + k = 10x - 3$, which simplifies to $4x^2 - 4x + (k + 3) = 0$. For exactly one real solution, the discriminant must equal zero: $(-4)^2 - 4(4)(k + 3) = 0$. This gives $16 - 16(k + 3) = 0$, so $16 - 16k - 48 = 0$, thus $-32 = 16k$ and $k = -2$. The distractor $-5$ arises from an arithmetic error when distributing $-16 \\times 3 = -48$, such as computing $16 - 48 = -64$ and then dividing by $16$ incorrectly. The distractor $-3$ comes from using only the constant term from the linear equation without completing the discriminant calculation. The distractor $2$ results from a sign error when solving $-32 = 16k$, obtaining $k = 2$ instead of $k = -2$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28M32DX', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'mcq', E'In right triangle $RST$ with the right angle at $T$, $\\tan(R) = \\frac{36}{77}$. If $ST = 72$, what is the length of the hypotenuse $RS$?', NULL, $lyceon_json$[{"key":"A","text":"$85$"},{"key":"B","text":"$154$"},{"key":"C","text":"$170$"},{"key":"D","text":"$226$"}]$lyceon_json$::jsonb, 'C', NULL, E'Since $\\tan(R) = \\frac{\\text{opposite}}{\\text{adjacent}} = \\frac{ST}{RT} = \\frac{36}{77}$, let $ST = 36k$ and $RT = 77k$. The hypotenuse is $RS = \\sqrt{(36k)^2 + (77k)^2} = \\sqrt{1296k^2 + 5929k^2} = \\sqrt{7225k^2} = 85k$. Since $ST = 72$, we have $36k = 72$, so $k = 2$. Therefore $RS = 85(2) = 170$. The value $85$ is the unscaled base-ratio hypotenuse ($\\sqrt{36^2 + 77^2} = 85$) before applying the scaling factor, stopping at an intermediate step. The value $154$ is the adjacent leg $RT = 77(2) = 154$, reporting a leg instead of the hypotenuse. The value $226$ comes from adding $72 + 154 = 226$ rather than applying the Pythagorean relationship.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28WFWXL', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'grid_in', E'A line passes through the points $(3, 7)$ and $(6, 19)$. What is the $y$-intercept of this line?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-5', ARRAY['-5'], E'The slope is $\\frac{19 - 7}{6 - 3} = \\frac{12}{3} = 4$. Using point-slope form with $(3, 7)$: $y - 7 = 4(x - 3)$, which gives $y = 4x - 5$. The $y$-intercept is $-5$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2A7NH9B', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'A printing company has $2{,}730$ sheets of paper in stock. Each print job uses exactly $39$ sheets. After completing a series of identical print jobs, $546$ sheets remain. How many print jobs were completed?', NULL, $lyceon_json$[{"key":"A","text":"$14$"},{"key":"B","text":"$56$"},{"key":"C","text":"$70$"},{"key":"D","text":"$84$"}]$lyceon_json$::jsonb, 'B', NULL, E'The number of sheets remaining after $j$ print jobs is $2{,}730 - 39j$. Setting this equal to $546$: $2{,}730 - 39j = 546$. Subtracting $2{,}730$ from both sides gives $-39j = -2{,}184$, so $j = 56$. The value $14$ arises from misreading the question, dividing the remaining $546$ sheets by $39$ as if $546$ were the amount used rather than the amount left. The value $70$ comes from an equation setup error, dividing $2{,}730$ by $39$ to find how many jobs would exhaust all sheets, ignoring that $546$ sheets remain. The value $84$ results from partial reasoning, incorrectly adding $70$ and $14$ together instead of computing the difference.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2A9OUJL', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'In triangle $PQR$, the measure of angle $P$ is $51^\\circ$ and the measure of angle $Q$ is $67^\\circ$. What is the measure, in degrees, of angle $R$?', NULL, $lyceon_json$[{"key":"A","text":"$16^\\circ$"},{"key":"B","text":"$62^\\circ$"},{"key":"C","text":"$118^\\circ$"},{"key":"D","text":"$129^\\circ$"}]$lyceon_json$::jsonb, 'B', NULL, E'The sum of the interior angles of a triangle is $180^\\circ$. So angle $R = 180^\\circ - 51^\\circ - 67^\\circ = 62^\\circ$. The value $16^\\circ$ results from subtracting the two given angles from each other ($67 - 51 = 16$) instead of subtracting their sum from $180$. The value $118^\\circ$ comes from adding the two given angles ($51 + 67 = 118$) and treating the sum as the missing angle rather than subtracting from $180$. The value $129^\\circ$ is the result of subtracting only one angle from $180^\\circ$ ($180 - 51 = 129$), stopping before subtracting the second.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2B8Q0OA', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'grid_in', E'If $7x^2 - 29x + 4 = 0$, what is the smaller value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '1/7', ARRAY['1/7', '0.142', '.142', '0.143', '.143'], E'Using the quadratic formula: $x = \\frac{29 \\pm \\sqrt{(-29)^2 - 4(7)(4)}}{2(7)} = \\frac{29 \\pm \\sqrt{841 - 112}}{14} = \\frac{29 \\pm \\sqrt{729}}{14} = \\frac{29 \\pm 27}{14}$. This gives $x = \\frac{56}{14} = 4$ or $x = \\frac{2}{14} = \\frac{1}{7}$. The smaller value is $\\frac{1}{7}$. This can be verified by factoring: $7x^2 - 29x + 4 = (7x - 1)(x - 4) = 0$, giving $x = \\frac{1}{7}$ or $x = 4$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DFL2CY', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'grid_in', E'A triangular prism has a base that is a right triangle with legs of length $7$ cm and $10$ cm. The height (length) of the prism is $18$ cm. What is the volume of the prism, in cubic centimeters?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '630', ARRAY['630'], E'The volume of a prism is $V = Bh$, where $B$ is the area of the base and $h$ is the height of the prism. The base is a right triangle with legs $7$ and $10$, so $B = \\frac{1}{2}(7)(10) = 35$ square centimeters. Therefore $V = 35 \\times 18 = 630$ cubic centimeters.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DOY6JD', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following is equivalent to $9(4x - 3) + 7x$?', NULL, $lyceon_json$[{"key":"A","text":"$36x - 27$"},{"key":"B","text":"$43x - 3$"},{"key":"C","text":"$43x - 27$"},{"key":"D","text":"$43x + 27$"}]$lyceon_json$::jsonb, 'C', NULL, E'Distributing the $9$ gives $9(4x - 3) + 7x = 36x - 27 + 7x = 43x - 27$. The distractor $36x - 27$ correctly distributes but omits the $+7x$ term, stopping after only the first step. The distractor $43x - 3$ correctly combines $36x + 7x = 43x$ but fails to multiply $9 \\times 3$, leaving the constant as $-3$ instead of $-27$. The distractor $43x + 27$ correctly finds $43x$ but applies a sign error to the constant, writing $+27$ instead of $-27$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DQW4PY', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'A research firm surveys a random sample of $850$ adults in a county and finds that $44\\%$ support a proposed transit expansion while $56\\%$ oppose it, each with a margin of error of $2.6\\%$. A county official states: "There is no meaningful difference in opinion — the community is essentially divided." Which of the following best evaluates the official''s claim?', NULL, $lyceon_json$[{"key":"A","text":"The claim is justified because both percentages are close to $50\\%$."},{"key":"B","text":"The claim is justified because a margin of error of $2.6\\%$ means the true values could be anywhere within $2.6\\%$ of each other."},{"key":"C","text":"The claim is not justified because the confidence intervals ($41.4\\%$ to $46.6\\%$ for support and $53.4\\%$ to $58.6\\%$ for opposition) do not overlap, indicating the difference is statistically meaningful."},{"key":"D","text":"The claim is not justified because the sample of $850$ adults is too small to represent an entire county."}]$lyceon_json$::jsonb, 'C', NULL, E'The confidence interval for support is $44\\% \\pm 2.6\\%$, or $41.4\\%$ to $46.6\\%$, and for opposition is $56\\% \\pm 2.6\\%$, or $53.4\\%$ to $58.6\\%$. These intervals do not overlap — the upper bound for support ($46.6\\%$) is below the lower bound for opposition ($53.4\\%$) — so the data indicate a statistically meaningful difference, contradicting the official''s claim that the community is essentially divided. The justification based on both percentages being close to $50\\%$ uses partial reasoning by ignoring the margin of error and the fact that the gap of $12$ percentage points far exceeds the combined margins. The claim that true values could be anywhere within $2.6\\%$ of each other misinterprets how margins of error work — each proportion has its own interval, and the intervals are separate. The claim that $850$ adults is too small reflects a misunderstanding of sampling — $850$ is a substantial sample that yields a relatively precise margin of error of $2.6\\%$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EU3R0N', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'Which of the following points $(x, y)$ lies in the solution region of both $5x - 7y \\geq 23$ and $3x + 11y < 40$?', NULL, $lyceon_json$[{"key":"A","text":"$(2, 4)$"},{"key":"B","text":"$(6, 1)$"},{"key":"C","text":"$(9, 2)$"},{"key":"D","text":"$(4, 3)$"}]$lyceon_json$::jsonb, 'B', NULL, E'Substituting $(6, 1)$: the first inequality gives $5(6) - 7(1) = 30 - 7 = 23 \\geq 23$, which is true, and the second gives $3(6) + 11(1) = 18 + 11 = 29 < 40$, which is also true. The point $(2, 4)$ fails the first inequality because $5(2) - 7(4) = 10 - 28 = -18$, which is not $\\geq 23$, reflecting a concept gap about how subtracting a large $y$-term produces a negative result far from the boundary. The point $(9, 2)$ satisfies the first inequality ($5(9) - 7(2) = 45 - 14 = 31 \\geq 23$) but fails the second ($3(9) + 11(2) = 27 + 22 = 49$, which is not less than 40), reflecting a failure to check both constraints. The point $(4, 3)$ fails the first inequality because $5(4) - 7(3) = 20 - 21 = -1$, which is not $\\geq 23$, likely from a sign error in estimating how the expression evaluates with these coordinates.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GI0AWK', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A university surveys a random sample of $150$ alumni and finds that $39\\%$ donate annually. A second survey of a random sample of $600$ alumni at the same university finds that $42\\%$ donate annually, with a smaller margin of error. Which of the following best explains why the second survey has a smaller margin of error?', NULL, $lyceon_json$[{"key":"A","text":"The second survey found a higher donation rate, which decreases the margin of error."},{"key":"B","text":"The second survey sampled four times as many alumni, which decreases the margin of error."},{"key":"C","text":"The second survey was administered online, which produces more accurate responses."},{"key":"D","text":"The second survey contacted more recent graduates who are easier to reach."}]$lyceon_json$::jsonb, 'B', NULL, E'The margin of error is inversely related to the square root of the sample size. The second survey sampled $600$ alumni compared to $150$, a fourfold increase, so its margin of error is approximately halved. The claim that a higher donation rate decreases the margin of error conflates the value of the statistic with sampling precision — while the proportion has a minor effect on margin of error, the dominant factor here is the much larger sample size. The suggestion about online administration introduces an unsubstantiated factor unrelated to how margin of error is calculated from sample size. The claim about contacting more recent graduates is an irrelevant demographic detail that does not explain the statistical relationship between sample size and margin of error.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HOCI44', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A paint mixture uses red pigment and white base in a ratio of $7:4$ by volume. If a painter has 308 milliliters of red pigment, how many milliliters of white base are needed to maintain this ratio?', NULL, $lyceon_json$[{"key":"A","text":"$44$"},{"key":"B","text":"$77$"},{"key":"C","text":"$176$"},{"key":"D","text":"$539$"}]$lyceon_json$::jsonb, 'C', NULL, E'Using the ratio $\\frac{7}{4} = \\frac{308}{w}$, cross-multiplying gives $7w = 308 \\times 4 = 1232$, so $w = \\frac{1232}{7} = 176$ milliliters. The value 44 results from dividing $308 \\div 7 = 44$ but stopping there without multiplying by 4 to get the white base amount. The value 77 comes from dividing $308 \\div 4 = 77$, dividing by the white-base part of the ratio instead of the red-pigment part. The value 539 results from applying the ratio in reverse, computing $308 \\times \\frac{7}{4} = 539$, which would give the amount of red pigment needed for 308 mL of white base.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IMNFHK', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'grid_in', E'A ceramics workshop charges a one-time registration fee of $\\$79$ plus $\\$19$ per session. A participant has a budget of at most $\\$436$ for the workshop. What is the maximum number of sessions the participant can attend?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '18', ARRAY['18'], E'The total cost for $n$ sessions is $19n + 79$. The inequality is $19n + 79 \\leq 436$. Subtracting 79 from both sides gives $19n \\leq 357$. Dividing by 19 gives $n \\leq 18.789\\ldots$. Since $n$ must be a whole number, the maximum is $18$. A common error is forgetting to subtract the registration fee, dividing $436$ by $19$ to get approximately $22.9$ and answering $22$. Another error is computing $436 - 79 = 357$ correctly but dividing by an incorrect value.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2J756IZ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'Two parallel lines are cut by a transversal. A pair of co-interior (same-side interior) angles have measures $(6x + 7)^\\circ$ and $(5x + 8)^\\circ$. What is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$1$"},{"key":"B","text":"$11$"},{"key":"C","text":"$15$"},{"key":"D","text":"$97$"}]$lyceon_json$::jsonb, 'C', NULL, E'Co-interior angles formed by parallel lines and a transversal are supplementary, so $(6x + 7) + (5x + 8) = 180$. Simplifying: $11x + 15 = 180$, giving $11x = 165$ and $x = 15$. Verification: $6(15) + 7 = 97^\\circ$ and $5(15) + 8 = 83^\\circ$, and $97 + 83 = 180^\\circ$. The value $1$ comes from incorrectly setting the angles equal ($6x + 7 = 5x + 8$, yielding $x = 1$), confusing co-interior angles with alternate interior angles. The value $11$ results from an arithmetic slip during the solving process, such as dividing $165$ by $15$ instead of by $11$. The value $97$ is one of the angle measures ($6(15) + 7 = 97$), not the value of $x$, reflecting partial reasoning that computes an intermediate result but reports the wrong quantity.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JBKIDB', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A hospital randomly assigns $114$ patients with chronic back pain to two groups. One group receives a new targeted exercise program, and the other group receives the standard care protocol. After $14$ weeks, patients in the new exercise program report significantly lower pain scores on average. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"The new exercise program is effective for all types of chronic pain."},{"key":"B","text":"Patients who preferred the exercise program experienced lower pain because of their positive expectations."},{"key":"C","text":"The new exercise program likely caused the reduction in pain scores among the patients in this experiment."},{"key":"D","text":"There is an association between the exercise program and lower pain scores, but causation cannot be determined."}]$lyceon_json$::jsonb, 'C', NULL, E'Because patients were randomly assigned to groups, this is a randomized experiment. Random assignment controls for confounding variables such as age, pain severity, or activity level, so a causal conclusion about the exercise program''s effect is appropriate for the study population. The claim about all types of chronic pain overgeneralizes beyond the study''s population of chronic back pain patients at one hospital. The claim about patients preferring the program contradicts the study design — random assignment means patients did not choose their treatment, so preference-based bias does not apply. The claim that causation cannot be determined applies to observational studies, not to properly randomized experiments where establishing causal relationships is the fundamental purpose of the design.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JJY4IR', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a diameter of $34$ units. What is the circumference of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$17\\pi$"},{"key":"B","text":"$34\\pi$"},{"key":"C","text":"$68\\pi$"},{"key":"D","text":"$289\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'The circumference of a circle is $C = \\pi d = \\pi(34) = 34\\pi$. The value $17\\pi$ results from halving the diameter to get the radius ($17$) and then computing $\\pi r$ instead of $2\\pi r$, stopping one step short. The value $68\\pi$ comes from using $2\\pi d$ instead of $\\pi d$, incorrectly doubling the diameter in the circumference formula. The value $289\\pi$ results from computing $\\pi(17)^2 = 289\\pi$, confusing the area formula with the circumference formula.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JS08VF', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'A bag contains $13$ red tokens and $9$ blue tokens. Two tokens are drawn one at a time without replacement. Given that the first token drawn is red, what is the probability that the second token drawn is blue?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{9}{22}$"},{"key":"B","text":"$\\frac{9}{21}$"},{"key":"C","text":"$\\frac{8}{21}$"},{"key":"D","text":"$\\frac{9}{23}$"}]$lyceon_json$::jsonb, 'B', NULL, E'After one red token is drawn, $21$ tokens remain: $12$ red and $9$ blue. The conditional probability that the second token is blue is $\\frac{9}{21}$, which simplifies to $\\frac{3}{7}$. The distractor $\\frac{9}{22}$ uses the original total of $22$ tokens in the denominator, failing to account for the without-replacement condition that removes one token. The distractor $\\frac{8}{21}$ correctly reduces the total to $21$ but also subtracts one from the blue count, incorrectly applying the removal to the wrong color. The distractor $\\frac{9}{23}$ adds one to the original total instead of subtracting, an arithmetic error in tracking the remaining tokens.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KF1BHC', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'Nine students scored the following on a quiz: $53, 61, 67, 72, 72, 78, 85, 91, 97$. If the score of 97 is replaced by 73, which of the following correctly describes the effect on the mean and the median?', NULL, $lyceon_json$[{"key":"A","text":"The mean decreases and the median stays the same."},{"key":"B","text":"The mean stays the same and the median decreases."},{"key":"C","text":"Both the mean and the median decrease."},{"key":"D","text":"The mean decreases and the median increases."}]$lyceon_json$::jsonb, 'A', NULL, E'The original nine scores in order are $53, 61, 67, 72, 72, 78, 85, 91, 97$. The original sum is $676$, giving a mean of $\\frac{676}{9} \\approx 75.1$. The median is the 5th value, which is $72$. After replacing 97 with 73, the new ordered set is $53, 61, 67, 72, 72, 73, 78, 85, 91$. The new sum is $676 - 97 + 73 = 652$, giving a mean of $\\frac{652}{9} \\approx 72.4$, which is lower. The new median is still the 5th value, which remains $72$. Therefore the mean decreases and the median stays the same. The claim that both decrease is incorrect because the 5th value in the ordered list is unchanged. The claim that the median increases has no basis since no value below the original median was affected.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2L7XG8Z', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'grid_in', E'A data set of 14 points has a line of best fit given by $y = 2.6x - 5.8$. One of the data points is $(7, k)$, and the residual for this point is $-1.4$. What is the value of $k$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '11', ARRAY['11'], E'The predicted value at $x = 7$ is $y = 2.6(7) - 5.8 = 18.2 - 5.8 = 12.4$. The residual is defined as the actual value minus the predicted value, so $k - 12.4 = -1.4$. Solving gives $k = 12.4 - 1.4 = 11$. A common error is adding the residual to the predicted value with the wrong sign, computing $12.4 + 1.4 = 13.8$, which would correspond to a positive residual of $1.4$ rather than $-1.4$. Another error is confusing the residual formula and computing $12.4 - (-1.4) = 13.8$ by treating the subtraction of a negative residual incorrectly.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LBRY46', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A warehouse has 450 items in stock. If $22\\%$ of the items are on clearance, how many items are on clearance?', NULL, $lyceon_json$[{"key":"A","text":"$22$"},{"key":"B","text":"$90$"},{"key":"C","text":"$99$"},{"key":"D","text":"$351$"}]$lyceon_json$::jsonb, 'C', NULL, E'The number of clearance items is $0.22 \\times 450 = 99$. The value 22 results from mistaking the percentage itself for the count of items. The value 90 comes from computing $20\\%$ of 450 instead of $22\\%$, yielding $0.20 \\times 450 = 90$. The value 351 is the number of items NOT on clearance ($450 - 99 = 351$), which answers the wrong question.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LHQZJE', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $g$ is defined by $g(x) = a \\cdot b^x + c$, where $a$, $b$, and $c$ are constants. The graph of $g$ has a horizontal asymptote at $y = -5$ and passes through the points $(0, 7)$ and $(2, 295)$. What is the value of $b$?', NULL, $lyceon_json$[{"key":"A","text":"$-5$"},{"key":"B","text":"$5$"},{"key":"C","text":"$12$"},{"key":"D","text":"$25$"}]$lyceon_json$::jsonb, 'B', NULL, E'The horizontal asymptote at $y = -5$ means $c = -5$. Substituting the point $(0, 7)$: $g(0) = a \\cdot b^0 + (-5) = a - 5 = 7$, so $a = 12$. Substituting the point $(2, 295)$: $g(2) = 12 \\cdot b^2 - 5 = 295$, so $12b^2 = 300$ and $b^2 = 25$. Since $b > 0$ for an exponential function, $b = 5$. The distractor $-5$ confuses the horizontal asymptote value $c = -5$ with the base $b$, reflecting a gap in understanding which parameter controls the asymptote versus the growth rate. The distractor $12$ is the value of $a$, not $b$, resulting from misidentifying which constant the question asks for. The distractor $25$ comes from correctly computing $b^2 = 25$ but failing to take the square root, returning the intermediate result instead of the final answer.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LMU2D7', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'What is the solution to the equation $8(x - 5) = 3x + 5$?', NULL, $lyceon_json$[{"key":"A","text":"$x = -9$"},{"key":"B","text":"$x = 2$"},{"key":"C","text":"$x = 7$"},{"key":"D","text":"$x = 9$"}]$lyceon_json$::jsonb, 'D', NULL, E'Distributing gives $8x - 40 = 3x + 5$. Subtracting $3x$ from both sides: $5x - 40 = 5$. Adding $40$ to both sides: $5x = 45$. Dividing by $5$: $x = 9$. The value $-9$ results from a sign error when dividing $45$ by $5$, incorrectly attaching a negative sign. The value $2$ comes from an equation setup error — failing to distribute the $8$ to $-5$, treating the equation as $8x - 5 = 3x + 5$, which gives $5x = 10$ and $x = 2$. The value $7$ arises from an arithmetic slip — computing $5 + 40$ as $35$ instead of $45$, yielding $5x = 35$ and $x = 7$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LRHD4C', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'mcq', E'A rectangular prism has dimensions $16$ cm $\\times$ $9$ cm $\\times$ $12$ cm. A cylindrical hole with diameter $6$ cm is drilled through the entire $12$-cm length of the prism. What is the volume, in cubic centimeters, of the remaining solid?', NULL, $lyceon_json$[{"key":"A","text":"$1728 - 108\\pi$"},{"key":"B","text":"$1728 - 216\\pi$"},{"key":"C","text":"$1728 - 432\\pi$"},{"key":"D","text":"$1620$"}]$lyceon_json$::jsonb, 'A', NULL, E'The volume of the rectangular prism is $16 \\times 9 \\times 12 = 1728$ cubic centimeters. The cylindrical hole has diameter $6$ cm, so its radius is $3$ cm. The cylinder''s volume is $\\pi r^2 h = \\pi(3)^2(12) = 108\\pi$ cubic centimeters. The remaining solid has volume $1728 - 108\\pi$. The expression $1728 - 216\\pi$ arises from an arithmetic slip such as doubling the cylinder volume ($2 \\times 108\\pi = 216\\pi$). The expression $1728 - 432\\pi$ results from using the diameter $6$ as the radius, computing $\\pi(6)^2(12) = 432\\pi$, an error in distinguishing radius from diameter. The value $1620$ subtracts $108$ without the factor of $\\pi$ ($1728 - 108 = 1620$), dropping $\\pi$ from the cylinder volume formula.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LXYOK3', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'grid_in', E'The eleven values in a data set, listed in increasing order, are $8, 14, k, 27, 31, 35, 39, 44, 51, 57, 63$. If the interquartile range of the data set is $29$, what is the value of $k$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '22', ARRAY['22'], E'For a data set of 11 values listed in increasing order, the median is the 6th value, which is $35$. The lower half consists of the first 5 values: $8, 14, k, 27, 31$. The first quartile $Q_1$ is the median of this lower half, which is the 3rd value: $k$. The upper half consists of the last 5 values: $39, 44, 51, 57, 63$. The third quartile $Q_3$ is the median of this upper half, which is the 3rd value of that group: $51$. The interquartile range is $Q_3 - Q_1 = 51 - k = 29$, so $k = 51 - 29 = 22$. This value is valid because $14 < 22 < 27$, confirming it fits in the increasing order. A common error is using $Q_3 = 44$ (the 8th value) instead of 51, which gives $k = 15$. Another error is computing $Q_1$ as the average of the 3rd and 4th values rather than just the 3rd, leading to an equation with $k$ that yields a different result.', NULL, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2M0KU4S', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'grid_in', E'In right triangle $JKL$ with the right angle at $L$, $\\sin(J) = \\frac{13}{85}$. What is $\\cos(J)$? Express your answer as a fraction.', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '84/85', ARRAY['84/85', '0.988', '.988'], E'Since $\\sin(J) = \\frac{\\text{opposite}}{\\text{hypotenuse}} = \\frac{13}{85}$, the side opposite angle $J$ (which is $KL$) has length $13$ and the hypotenuse $JK$ has length $85$. By the Pythagorean theorem, the adjacent side $JL = \\sqrt{85^2 - 13^2} = \\sqrt{7225 - 169} = \\sqrt{7056} = 84$. Therefore $\\cos(J) = \\frac{\\text{adjacent}}{\\text{hypotenuse}} = \\frac{84}{85}$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MCXIY7', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'mcq', E'A delivery truck drives the first 45 kilometers at an average speed of 15 kilometers per hour and the remaining 40 kilometers at an average speed of 20 kilometers per hour. What is the truck''s average speed, in kilometers per hour, for the entire trip?', NULL, $lyceon_json$[{"key":"A","text":"$15$"},{"key":"B","text":"$17$"},{"key":"C","text":"$17.5$"},{"key":"D","text":"$20$"}]$lyceon_json$::jsonb, 'B', NULL, E'Time for the first segment: $\\frac{45}{15} = 3$ hours. Time for the second segment: $\\frac{40}{20} = 2$ hours. Total distance: $45 + 40 = 85$ km. Total time: $3 + 2 = 5$ hours. Average speed: $\\frac{85}{5} = 17$ km/h. The value 15 results from reporting only the speed of the first segment and ignoring the second. The value 17.5 comes from simply averaging the two speeds as $\\frac{15 + 20}{2} = 17.5$, which is incorrect because the truck spent different amounts of time at each speed. The value 20 results from reporting only the speed of the second segment.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MUSA72', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the $x$-intercept of the line $5x - 2y = 30$?', NULL, $lyceon_json$[{"key":"A","text":"$(-6, 0)$"},{"key":"B","text":"$(0, -15)$"},{"key":"C","text":"$(0, 6)$"},{"key":"D","text":"$(6, 0)$"}]$lyceon_json$::jsonb, 'D', NULL, E'The $x$-intercept occurs where $y = 0$. Substituting gives $5x = 30$, so $x = 6$, and the intercept is $(6, 0)$. The point $(-6, 0)$ results from a sign error, incorrectly attaching a negative sign when dividing $30$ by $5$. The point $(0, -15)$ is the $y$-intercept — setting $x = 0$ gives $-2y = 30$, so $y = -15$ — indicating the question was misread. The point $(0, 6)$ reflects a concept gap, placing the $x$-intercept value of $6$ in the $y$-coordinate instead.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NSEH7V', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A line of best fit for a data set is given by $y = 1.8x + 23$. When $x = 11$, the actual observed value of $y$ is $47$. What is the residual for this observation?', NULL, $lyceon_json$[{"key":"A","text":"$-4.2$"},{"key":"B","text":"$4.2$"},{"key":"C","text":"$42.8$"},{"key":"D","text":"$47$"}]$lyceon_json$::jsonb, 'B', NULL, E'The predicted value at $x = 11$ is $y = 1.8(11) + 23 = 19.8 + 23 = 42.8$. The residual is the actual value minus the predicted value: $47 - 42.8 = 4.2$. The value $-4.2$ results from reversing the subtraction order, computing predicted minus actual ($42.8 - 47 = -4.2$) instead of actual minus predicted. The value $42.8$ is the predicted value itself, not the difference between actual and predicted. The value $47$ is simply the given actual value, not the residual.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 65, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OAR1YB', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $f$ is defined by $f(x) = -3(x - 2)^2 + 8$. The graph of $y = f(x + 6)$ has a vertex at which of the following points?', NULL, $lyceon_json$[{"key":"A","text":"$(-4, 8)$"},{"key":"B","text":"$(2, 14)$"},{"key":"C","text":"$(8, 2)$"},{"key":"D","text":"$(8, 8)$"}]$lyceon_json$::jsonb, 'A', NULL, E'The vertex of $f(x) = -3(x - 2)^2 + 8$ is at $(2, 8)$. Replacing $x$ with $x + 6$ in $f$ shifts the graph $6$ units to the left: $f(x + 6) = -3((x + 6) - 2)^2 + 8 = -3(x + 4)^2 + 8$, so the new vertex is $(-4, 8)$. The distractor $(2, 14)$ adds $6$ to the $y$-coordinate instead of shifting horizontally, confusing horizontal and vertical transformations. The distractor $(8, 2)$ shifts the vertex $6$ units to the right instead of to the left and also incorrectly subtracts $6$ from the $y$-coordinate. The distractor $(8, 8)$ shifts the $x$-coordinate $6$ units to the right instead of to the left, reversing the direction of the horizontal shift.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PV5H30', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'grid_in', E'A bottling machine fills 37 bottles every 5 minutes. At this rate, how many bottles does the machine fill in 35 minutes?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '259', ARRAY['259'], E'The rate is $\\frac{37}{5}$ bottles per minute, which equals $7.4$ bottles per minute. In 35 minutes the machine fills $7.4 \\times 35 = 259$ bottles. Equivalently, $35 \\div 5 = 7$, so the machine runs for $7$ intervals of 5 minutes, producing $37 \\times 7 = 259$ bottles. A common error is multiplying $37 \\times 35 = 1295$, failing to divide by the 5-minute interval. Another error is dividing $35 \\div 37 \\approx 0.946$, confusing which quantity is the rate and which is the time.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QL5H93', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'A farm stand sells jars of honey for $h$ dollars each and bags of granola for $g$ dollars each. If 5 jars of honey and 2 bags of granola cost $\\$67$, and 3 jars of honey and 2 bags of granola cost $\\$47$, what is the cost, in dollars, of one jar of honey?', NULL, $lyceon_json$[{"key":"A","text":"$\\$6$"},{"key":"B","text":"$\\$8.50$"},{"key":"C","text":"$\\$10$"},{"key":"D","text":"$\\$20$"}]$lyceon_json$::jsonb, 'C', NULL, E'The system is $5h + 2g = 67$ and $3h + 2g = 47$. Subtracting the second equation from the first eliminates $g$: $2h = 20$, so $h = 10$. One jar of honey costs $\\$10$. Substituting back: $50 + 2g = 67$, so $2g = 17$ and $g = 8.50$. The distractor $\\$6$ could arise from misreading the question and confusing which variable to solve for or setting up the subtraction incorrectly. The distractor $\\$8.50$ is actually the price of granola, not honey, resulting from an arithmetic slip where the solver finds $g$ instead of $h$. The distractor $\\$20$ results from stopping at $2h = 20$ and reporting the intermediate value without dividing by 2.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QR92V4', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $g(x) = (x + 11)^2 - 23$ has a minimum value. What is this minimum value?', NULL, $lyceon_json$[{"key":"A","text":"$-23$"},{"key":"B","text":"$-11$"},{"key":"C","text":"$11$"},{"key":"D","text":"$23$"}]$lyceon_json$::jsonb, 'A', NULL, E'The function $g(x) = (x + 11)^2 - 23$ is in vertex form $a(x - h)^2 + k$ with $a = 1 > 0$, so the parabola opens upward and the vertex $(-11, -23)$ is the minimum point. The minimum value of $g(x)$ is $-23$. The distractor $-11$ confuses the $x$-coordinate of the vertex with the minimum output value. The distractor $11$ identifies the magnitude of the $x$-coordinate of the vertex and takes it as positive, misreading what the question asks. The distractor $23$ negates the minimum value, applying a sign error to the constant $-23$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RXO4S7', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What is the positive value of $x$ such that $3x^2 = 147$?', NULL, $lyceon_json$[{"key":"A","text":"$-7$"},{"key":"B","text":"$7$"},{"key":"C","text":"$24.5$"},{"key":"D","text":"$49$"}]$lyceon_json$::jsonb, 'B', NULL, E'Dividing both sides of $3x^2 = 147$ by $3$ gives $x^2 = 49$. Taking the positive square root yields $x = 7$. The distractor $-7$ is the negative square root, which does not satisfy the condition that $x$ be positive. The distractor $24.5$ results from dividing $147$ by $6$ (as if the equation were $6x = 147$) rather than dividing by $3$ and then taking the square root. The distractor $49$ comes from dividing $147$ by $3$ correctly to get $x^2 = 49$ but stopping there without taking the square root.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2S6MYRE', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A music school has two ensembles: jazz band and orchestra. Of the $83$ students, $37$ are in the jazz band and $46$ are in the orchestra. Among jazz band members, $14$ also play piano, and among orchestra members, $27$ also play piano. If a student is selected at random from those who play piano, what is the probability that the student is in the orchestra?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{27}{83}$"},{"key":"B","text":"$\\frac{27}{46}$"},{"key":"C","text":"$\\frac{27}{41}$"},{"key":"D","text":"$\\frac{14}{41}$"}]$lyceon_json$::jsonb, 'C', NULL, E'The condition restricts the sample space to students who play piano: $14 + 27 = 41$ total piano players. Of these, $27$ are in the orchestra, so the conditional probability is $\\frac{27}{41}$. The distractor $\\frac{27}{83}$ uses the entire student body as the denominator, computing the unconditional probability rather than conditioning on piano players. The distractor $\\frac{27}{46}$ uses the total number of orchestra members as the denominator instead of the total number of piano players, confusing the conditioning event. The distractor $\\frac{14}{41}$ correctly identifies the piano-player total but uses the jazz band piano count in the numerator, answering for the wrong ensemble.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SFM9HK', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'grid_in', E'The function $h$ is defined by $h(x) = -13x + 247$. For what value of $x$ does $h(x) = 0$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '19', ARRAY['19'], E'Setting $h(x) = 0$ gives $-13x + 247 = 0$. Subtracting $247$ from both sides yields $-13x = -247$. Dividing both sides by $-13$ gives $x = 19$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SOD7ZY', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'In a club election, $38\\%$ of voters chose candidate R and $26\\%$ chose candidate S. The remaining voters split their votes equally among four other candidates. If candidate R received 190 votes, how many votes did each of the four other candidates receive?', NULL, $lyceon_json$[{"key":"A","text":"$36$"},{"key":"B","text":"$45$"},{"key":"C","text":"$130$"},{"key":"D","text":"$180$"}]$lyceon_json$::jsonb, 'B', NULL, E'Since candidate R received $38\\%$ of the votes and got 190 votes, the total number of voters is $\\frac{190}{0.38} = 500$. The remaining percentage is $100\\% - 38\\% - 26\\% = 36\\%$, so the remaining votes total $0.36 \\times 500 = 180$. Dividing equally among four candidates gives $\\frac{180}{4} = 45$ votes each. The value 36 results from dividing 180 by 5 instead of 4, perhaps by mistakenly counting candidate S among the other candidates. The value 130 is the number of votes candidate S received ($0.26 \\times 500 = 130$), not one of the four other candidates. The value 180 is the total remaining votes before dividing by 4, reflecting a failure to complete the final division step.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SV697K', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A fitness app company notices that users who log meals daily tend to lose more weight over a six-month period than users who do not log meals. Users choose whether or not to log meals. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"Logging meals daily causes greater weight loss."},{"key":"B","text":"There is an association between logging meals daily and greater weight loss."},{"key":"C","text":"Users who do not log meals should be required to start logging to improve their results."},{"key":"D","text":"The fitness app's meal-logging feature is more effective than competing apps' features."}]$lyceon_json$::jsonb, 'B', NULL, E'Because meal logging is voluntary, this is an observational study. Users who choose to log meals may differ from non-loggers in ways that also affect weight loss — for example, they may be more motivated, more disciplined with exercise, or more health-conscious overall. The data establish an association but cannot determine causation. The causal claim that logging meals causes weight loss is unwarranted without random assignment to logging and non-logging groups. The recommendation to require all users to log meals is a policy prescription that goes beyond what observational data can support. The comparison to competing apps introduces a claim about relative effectiveness that the study does not address, since no other apps were part of the observation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TFWELY', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which value of $p$ satisfies the inequality $9p - 17 > 56$?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$7$"},{"key":"C","text":"$8$"},{"key":"D","text":"$11$"}]$lyceon_json$::jsonb, 'D', NULL, E'Adding 17 to both sides gives $9p > 73$, and dividing by 9 gives $p > 8.\\overline{1}$. Among the choices, only $11$ is strictly greater than $8.\\overline{1}$, since $9(11) - 17 = 99 - 17 = 82 > 56$. The value $5$ gives $9(5) - 17 = 28$, which is far below 56, reflecting a concept gap about the magnitude needed. The value $7$ gives $9(7) - 17 = 46$, which does not exceed 56, possibly from an arithmetic slip such as computing $56 + 17 = 73$ but dividing by an incorrect number. The value $8$ gives $9(8) - 17 = 55$, which is one less than 56 and not strictly greater, reflecting confusion between $>$ and $\\geq$ or rounding prematurely.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UTPTPN', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A parallelogram has a base of $23$ centimeters and a height of $7$ centimeters. What is the area, in square centimeters, of the parallelogram?', NULL, $lyceon_json$[{"key":"A","text":"$60$"},{"key":"B","text":"$80.5$"},{"key":"C","text":"$161$"},{"key":"D","text":"$322$"}]$lyceon_json$::jsonb, 'C', NULL, E'The area of a parallelogram is $A = bh = 23 \\times 7 = 161$ square centimeters. The value $60$ comes from computing $2(23 + 7) = 60$, confusing the perimeter formula with the area formula. The value $80.5$ results from using the triangle area formula $\\frac{1}{2}bh = \\frac{1}{2}(23)(7) = 80.5$, incorrectly applying the half-factor that applies to triangles but not parallelograms. The value $322$ comes from doubling the correct area ($2 \\times 161 = 322$), an arithmetic slip such as computing $bh$ twice or confusing the formula with $2bh$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
