INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VRC2BN', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A jar contains $17$ green marbles, $9$ yellow marbles, and $11$ white marbles. If one marble is selected at random from the jar, what is the probability that the marble is yellow?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{9}{37}$"},{"key":"B","text":"$\\frac{9}{28}$"},{"key":"C","text":"$\\frac{17}{37}$"},{"key":"D","text":"$\\frac{11}{37}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total number of marbles is $17 + 9 + 11 = 37$. The probability of selecting a yellow marble is $\\frac{9}{37}$. The distractor $\\frac{9}{28}$ divides the yellow count by the number of non-yellow marbles ($17 + 11 = 28$) instead of the total, setting up the denominator incorrectly. The distractor $\\frac{17}{37}$ uses the count of green marbles in the numerator rather than yellow marbles. The distractor $\\frac{11}{37}$ uses the count of white marbles instead of yellow marbles.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WQKFFC', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'grid_in', E'In the $xy$-plane, a circle has equation $(x - 2)^2 + (y + 7)^2 = 289$. The line $y = 1$ intersects the circle at two points. What is the distance between these two points?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '30', ARRAY['30'], E'The circle has center $(2, -7)$ and radius $\\sqrt{289} = 17$. The perpendicular distance from the center to the line $y = 1$ is $|1 - (-7)| = 8$. A radius drawn to each intersection point and the perpendicular from the center to the chord form a right triangle, where the hypotenuse is the radius and one leg is the perpendicular distance. The half-chord length is $\\sqrt{17^2 - 8^2} = \\sqrt{289 - 64} = \\sqrt{225} = 15$. The full chord length is $2 \\times 15 = 30$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Z1YYAB', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of $270$ employees at a large company found that $51\\%$ prefer a four-day workweek, with a margin of error of $5\\%$. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Exactly $51\\%$ of all employees at the company prefer a four-day workweek."},{"key":"B","text":"Between $46\\%$ and $56\\%$ of the sampled employees prefer a four-day workweek."},{"key":"C","text":"It is plausible that between $46\\%$ and $56\\%$ of all employees at the company prefer a four-day workweek."},{"key":"D","text":"At least $46\\%$ of all employees at the company definitely prefer a four-day workweek."}]$lyceon_json$::jsonb, 'C', NULL, E'The margin of error creates a confidence interval around the sample statistic: $51\\% \\pm 5\\%$, or $46\\%$ to $56\\%$. This means it is plausible that the true population proportion falls within this range. The claim that exactly $51\\%$ of all employees prefer a four-day workweek treats the sample statistic as the exact population parameter, ignoring sampling variability. The claim about the sampled employees misapplies the interval — the margin of error addresses the population parameter, not the sample result, which is already known from the data. The claim that at least $46\\%$ definitely prefer it overstates the certainty of the interval — a confidence interval expresses plausibility, not absolute guarantees about the population parameter.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Z5B7NW', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'grid_in', E'What is the value of $y$ in the solution to the system of equations below?
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Z66GFX', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'A right triangle has legs of length $12$ and $35$. What is the length of the hypotenuse?', NULL, $lyceon_json$[{"key":"A","text":"$23$"},{"key":"B","text":"$34$"},{"key":"C","text":"$37$"},{"key":"D","text":"$47$"}]$lyceon_json$::jsonb, 'C', NULL, E'By the Pythagorean theorem, $c = \\sqrt{a^2 + b^2} = \\sqrt{12^2 + 35^2} = \\sqrt{144 + 1225} = \\sqrt{1369} = 37$. The value $23$ comes from subtracting the legs ($35 - 12 = 23$) instead of applying the Pythagorean theorem. The value $34$ results from an arithmetic slip, such as miscalculating the square root of $1369$. The value $47$ comes from adding the legs ($12 + 35 = 47$) rather than using the correct formula.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZQIMT5', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'What is the value of $x$ in the equation $$\\frac{4x - 3}{5} = \\frac{2x + 9}{3}\\;?$$', NULL, $lyceon_json$[{"key":"A","text":"$-27$"},{"key":"B","text":"$6$"},{"key":"C","text":"$18$"},{"key":"D","text":"$27$"}]$lyceon_json$::jsonb, 'D', NULL, E'Cross-multiplying gives $3(4x - 3) = 5(2x + 9)$, which expands to $12x - 9 = 10x + 45$. Subtracting $10x$ from both sides yields $2x - 9 = 45$. Adding $9$ to both sides gives $2x = 54$, so $x = 27$. The value $-27$ results from a sign error — incorrectly arriving at $2x = -54$ by subtracting $45$ and $9$ in the wrong direction. The value $6$ comes from an equation setup error — failing to distribute the cross-multiplication to every term, computing $12x - 3 = 10x + 9$ instead of $12x - 9 = 10x + 45$, which gives $2x = 12$ and $x = 6$. The value $18$ arises from an arithmetic slip — computing $45 - 9 = 36$ instead of $45 + 9 = 54$, yielding $2x = 36$ and $x = 18$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW215UM02', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Which choice best describes how the methodology in Text 2 complicates the conclusion drawn in Text 1?', E'Text 1
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21H8TUL', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The fleet of research vessels operated by the oceanographic institute _____ equipped with sonar arrays capable of mapping the seafloor at depths exceeding four thousand meters.', $lyceon_json$[{"key":"A","text":"is"},{"key":"B","text":"are"},{"key":"C","text":"have been"},{"key":"D","text":"were being"}]$lyceon_json$::jsonb, 'A', NULL, E'The subject is "fleet," a singular collective noun, not the plural noun "vessels" in the intervening prepositional phrase. The sentence describes a present condition, requiring the simple present tense. The singular present-tense "is" correctly agrees with "fleet" and maintains the present-tense frame. The plural form "are" would agree with "vessels" but not with the actual subject "fleet." The plural present perfect "have been" fails number agreement with the singular subject. The past progressive "were being" both fails number agreement and shifts to a past tense inconsistent with the sentence''s present description of the fleet''s current capabilities.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
