INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22NYANP', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'After the provincial government revised its forestry regulations, a consortium of timber companies _____ a legal challenge arguing that the new restrictions violated existing land-use agreements negotiated in the previous decade.', $lyceon_json$[{"key":"A","text":"launches"},{"key":"B","text":"launching"},{"key":"C","text":"launched"},{"key":"D","text":"has launched"}]$lyceon_json$::jsonb, 'C', NULL, E'The sentence establishes a past-tense frame with "revised" and continues with past-tense verbs such as "violated" and "negotiated." The simple past "launched" correctly matches this established tense. The present-tense "launches" breaks tense consistency by shifting to the present. The present participle "launching" is not a finite verb and cannot serve as the main predicate of the clause, producing a sentence fragment. The present perfect "has launched" implies present relevance, which is inconsistent with the past-tense narrative frame established by the surrounding verbs.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 85, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23H8ZYU', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Which choice best describes the relationship between the two passages?', E'Text 1
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW261WWJJ', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the passage, "economy" most nearly means', E'Choreographer Mirela Djuric is celebrated for the striking economy of her compositions: where other choreographers layer gesture upon gesture to build emotional intensity, Djuric achieves comparable impact through the deliberate reduction of movement to its most essential elements, sometimes restricting an entire three-minute solo to fewer than nine distinct gestures.', $lyceon_json$[{"key":"A","text":"frugality"},{"key":"B","text":"marketplace"},{"key":"C","text":"restraint"},{"key":"D","text":"inflation"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage describes Djuric''s approach of achieving impact through minimal, carefully selected movement rather than excess, reducing a solo to fewer than nine gestures. "Restraint" correctly captures this sense of deliberate, disciplined minimalism in artistic expression. "Frugality" means thriftiness with money or material resources, which is incoherent when describing the compositional principles of a dance choreographer''s movement vocabulary. "Marketplace" refers to a physical or abstract venue where goods are bought and sold, which has no logical application to the structure of choreographic works. "Inflation" means an increase in prices or the act of expanding something with air, neither of which has any connection to Djuric''s reductive approach to movement.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26JR5LG', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the passage?', E'The bombardier beetle defends itself by mixing two chemicals — hydroquinone and hydrogen peroxide — in a specialized reaction chamber inside its abdomen. When threatened, the beetle triggers an enzyme-catalyzed reaction that heats the mixture to nearly one hundred degrees Celsius and expels it as a boiling, noxious spray directed at the attacker.', $lyceon_json$[{"key":"A","text":"To explain how a specific insect produces a chemical defense mechanism"},{"key":"B","text":"To compare the defensive strategies of several beetle species found in the same habitat"},{"key":"C","text":"To argue that chemical defenses are more effective than physical armor in insects"},{"key":"D","text":"To chronicle the evolutionary history of abdomen-based glands in arthropods"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage identifies the two chemicals involved in the bombardier beetle''s defense, describes the reaction chamber where they are combined, and explains the resulting boiling spray — all focused on how one insect''s chemical defense works. Comparing defensive strategies of multiple beetle species mischaracterizes the passage, which discusses only the bombardier beetle and does not mention any other species. Arguing that chemical defenses are superior to physical armor introduces a comparative claim that the passage never makes; it describes a mechanism without ranking it against alternatives. Chronicling the evolutionary history of glands overstates the passage''s scope; it explains the present-day mechanism without tracing how it developed over evolutionary time.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26JY26I', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Cognitive neuroscientist Elara Mäkinen conducted an experiment in which 94 participants memorized a list of 26 unrelated words and were then tested on recall after a 12-hour interval. Half the participants spent the interval awake during daytime hours; the other half slept through it overnight. As expected from prior research, the sleep group recalled 31% more words on average. However, Mäkinen introduced a novel manipulation: before the recall test, she gave both groups a second list of 26 new words to memorize and tested them on this new list immediately. The wake group performed 14% better on the second list than the sleep group. Mäkinen noted that the sleep group''s superior recall of the first list and inferior performance on the second list arose under identical testing conditions — same room, same time of day, same cognitive load at test. She argued that sleep-dependent memory consolidation does not simply preserve existing memories but actively restructures the neural representations involved, and that this restructuring may temporarily ________', $lyceon_json$[{"key":"A","text":"reduce the brain's capacity to encode new information efficiently, because the neural resources devoted to consolidating older memories during sleep are not immediately available for forming new memory traces upon waking."},{"key":"B","text":"improve the brain's ability to learn new information by strengthening the synaptic connections used for all types of memory formation."},{"key":"C","text":"eliminate the brain's need for further sleep by completing the entire memory consolidation process in a single overnight cycle."},{"key":"D","text":"transfer consolidated memories from long-term storage back into short-term working memory, making them more vulnerable to interference from new information."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes that sleep improved recall of older memories but impaired learning of new material, and Mäkinen frames this as evidence that consolidation restructures neural representations. The logical completion is that this restructuring temporarily reduces the brain''s capacity to encode new information, because resources devoted to consolidation are not immediately available for new encoding. The option about improving new learning directly contradicts the experimental result — the sleep group performed worse on the second list, not better. The option about eliminating the need for further sleep introduces an extreme claim with no basis in the passage''s discussion of memory restructuring. The option about transferring consolidated memories back to short-term storage inverts the typical direction of consolidation described in the passage and introduces a vulnerability concept the passage does not suggest.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27QF1ZC', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding, if accurate, would most directly undermine Lindqvist and Farah''s explanation?', E'In a 2025 paper, materials scientists Karin Lindqvist and Omar Farah reported that thin films of bismuth selenide (Bi₂Se₃) deposited on sapphire substrates at 247 degrees Celsius exhibited electrical conductivity 19 times higher than films deposited at 310 degrees Celsius — the temperature recommended by prior literature. Lindqvist and Farah attributed this unexpected result to the lower deposition temperature producing a denser concentration of selenium vacancies — atomic-scale gaps where selenium atoms are missing from the crystal lattice. These vacancies, they argued, donate free electrons to the material''s conduction band, dramatically increasing its ability to carry electrical current. They supported this explanation by noting that X-ray diffraction patterns of the 247-degree films showed lattice parameter shifts consistent with elevated vacancy density.', $lyceon_json$[{"key":"A","text":"Electron microscopy of the 247-degree films reveals that they contain 23 times fewer selenium vacancies than the 310-degree films, despite showing the same lattice parameter shifts observed in Lindqvist and Farah's X-ray diffraction data."},{"key":"B","text":"Bismuth selenide films deposited on silicon substrates rather than sapphire show no conductivity difference between 247-degree and 310-degree deposition temperatures."},{"key":"C","text":"Other topological insulator materials, such as bismuth telluride, also show increased conductivity when deposited at temperatures below those recommended in the literature."},{"key":"D","text":"The 247-degree films degrade more rapidly when exposed to ambient atmosphere, losing approximately 40% of their enhanced conductivity within 72 hours of deposition."}]$lyceon_json$::jsonb, 'A', NULL, E'Lindqvist and Farah''s explanation hinges on the claim that lower deposition temperature produces more selenium vacancies, which donate free electrons and boost conductivity. If electron microscopy reveals that the 247-degree films actually contain far fewer vacancies than the 310-degree films, the core mechanism they propose collapses — higher conductivity cannot be attributed to vacancy-donated electrons if the high-conductivity films have fewer vacancies. The finding about silicon substrates introduces a different variable (substrate material) and could have multiple explanations unrelated to the vacancy mechanism. The finding about other topological insulators showing similar temperature effects is broadly consistent with, or at least does not contradict, the vacancy explanation. The finding about atmospheric degradation describes a practical limitation of the films but does not address whether selenium vacancies cause the enhanced conductivity.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27W2ITE', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Hydrologist Renata Cvijanović has demonstrated that the seasonal flooding patterns of the Sava River in Croatia have shifted measurably since 2003, with peak flood events now occurring an average of 19 days earlier than they did during the 1970–2000 baseline period. She attributes this shift primarily to accelerated snowmelt in the Julian Alps caused by rising spring temperatures. Ecologist Marko Zelić has studied how riparian plant communities along the Sava respond to flood timing and found that several native sedge species depend on late-spring inundation to trigger seed germination. _______ as the flood peak moves earlier into a period when soil temperatures remain too low for germination, these sedge populations have declined by an estimated 31% along monitored stretches of the river since 2010.', $lyceon_json$[{"key":"A","text":"Fortunately,"},{"key":"B","text":"Accordingly,"},{"key":"C","text":"Alternatively,"},{"key":"D","text":"Granted,"}]$lyceon_json$::jsonb, 'B', NULL, E'The sentence before the blank establishes that native sedge species require late-spring flooding for germination. The sentence after the blank describes the consequence: because the flood peak now arrives earlier when soil temperatures are too low, sedge populations have declined significantly. "Accordingly," correctly signals that the subsequent outcome follows logically from the established conditions -- the earlier floods cannot trigger germination, so the sedges decline. "Fortunately," implies the outcome is positive, but a 31% population decline is clearly detrimental. "Alternatively," introduces a different possibility or option, but the subsequent sentence describes an observed consequence, not an alternative scenario. "Granted," concedes a point that might weaken an argument, but the subsequent sentence strengthens the connection between flood-timing shifts and ecological harm rather than conceding a counterpoint.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27YTH8D', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The researchers noted that every one of the thirty-seven tissue samples collected from the estuary _____ significant concentrations of microplastic fibers, a finding that prompted the environmental agency to classify the waterway as critically impaired.', $lyceon_json$[{"key":"A","text":"contain"},{"key":"B","text":"have contained"},{"key":"C","text":"contained"},{"key":"D","text":"were containing"}]$lyceon_json$::jsonb, 'C', NULL, E'The subject of the clause is "every one," a singular indefinite expression, not the plural noun "samples" in the intervening prepositional phrase. The past tense is established by "noted," "collected," and "prompted." The singular past-tense "contained" correctly agrees with "every one" and maintains tense consistency. The plural present-tense "contain" fails on both number agreement with the singular subject and tense consistency with the past-tense frame. The plural present-perfect "have contained" fails number agreement and introduces a tense shift from the established past narrative. The plural past-progressive "were containing" fails number agreement with the singular subject, and "contain" is a stative verb that resists the progressive aspect in standard usage.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2AB88J5', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the passage?', E'Until the late 1990s, most volcanologists relied on seismic monitoring alone to forecast eruptions, interpreting patterns of small earthquakes beneath a volcano as indicators of rising magma. Geochemist Amara Diallo demonstrated that tracking the ratio of sulfur dioxide to carbon dioxide in volcanic gas emissions could detect magma movement weeks earlier than seismic signals. However, Diallo cautioned that gas-ratio monitoring is unreliable at volcanoes with extensive hydrothermal systems, where groundwater interactions can alter emission chemistry independently of magma activity, potentially generating false alarms.', $lyceon_json$[{"key":"A","text":"It describes a traditional forecasting method, introduces an alternative that offers earlier detection, and then identifies a limitation of the alternative"},{"key":"B","text":"It presents two competing eruption prediction models and concludes that neither is scientifically valid"},{"key":"C","text":"It proposes replacing seismic monitoring entirely with gas-ratio analysis and provides evidence supporting the replacement"},{"key":"D","text":"It traces the chronological development of volcanic monitoring technology from the 1990s through the present day"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage moves through three stages: it establishes the conventional reliance on seismic monitoring, presents Diallo''s gas-ratio method as a technique that can detect magma movement earlier, and then qualifies the new method by noting its unreliability at volcanoes with hydrothermal systems. Concluding that neither model is scientifically valid misrepresents the passage, which treats seismic monitoring as an established tool and gas-ratio analysis as a promising supplement with specific limitations — neither is dismissed as invalid. Proposing the complete replacement of seismic monitoring overstates Diallo''s position; the passage presents her method as offering earlier detection but also identifies conditions under which it fails, and it never advocates abandoning seismic approaches. Tracing the chronological development of monitoring technology misidentifies the passage''s structure; it contrasts two approaches and evaluates a limitation rather than providing a historical timeline of technological advancement.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2AY92LX', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Urban entomologist Kenji Furukawa has documented a 47% increase in solitary bee populations nesting within green roof installations across 11 buildings in Osaka since 2020. His team observed that native wildflower species planted on these rooftops bloom continuously from April through October, providing forage during months when ground-level gardens are often mowed. _______ Furukawa''s data show that rooftop nesting sites experience significantly lower rates of parasitism than ground-level nests, likely because parasitic wasps rarely ascend above five stories.', $lyceon_json$[{"key":"A","text":"In contrast,"},{"key":"B","text":"Additionally,"},{"key":"C","text":"For example,"},{"key":"D","text":"Consequently,"}]$lyceon_json$::jsonb, 'B', NULL, E'The sentence before the blank describes one advantage of green roofs for bees -- continuous forage availability. The sentence after the blank describes a separate, additional advantage -- lower parasitism rates at rooftop nesting sites. "Additionally," correctly signals that a second, supplementary benefit is being introduced alongside the first. "In contrast," implies the subsequent information opposes or differs from the preceding point, but both sentences describe benefits of rooftop habitats. "For example," would introduce a specific instance of the preceding claim, but lower parasitism is a separate advantage, not an example of forage availability. "Consequently," implies that the lower parasitism is a direct result of the continuous bloom, but the passage attributes the reduced parasitism to the altitude discouraging parasitic wasps, not to the availability of flowers.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CKV3PG', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Archaeologist Fatima al-Rashidi discovered fragments of a Bronze Age ceramic workshop beneath a modern olive grove in southeastern _____ she believes the kiln remnants indicate a previously undocumented trade route connecting inland settlements to coastal ports.', $lyceon_json$[{"key":"A","text":"Jordan, she"},{"key":"B","text":"Jordan she"},{"key":"C","text":"Jordan: she"},{"key":"D","text":"Jordan, and, she"}]$lyceon_json$::jsonb, 'C', NULL, E'Two independent clauses flank the blank, with the second clause elaborating on the significance of the discovery described in the first. A colon correctly introduces the second clause as an explanation or amplification of the first. Using only a comma creates a comma splice between two independent clauses. Omitting all punctuation produces a fused sentence. Inserting extraneous commas around a conjunction ("and, she") disrupts the grammatical connection with unnecessary punctuation that separates the conjunction from the clause it introduces.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 85, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CP79F0', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Landscape architect Tomoko Nishikawa redesigned the municipal botanical garden in Sapporo, _____ a project that required relocating over eleven hundred native plant specimens to temporary greenhouses during the eighteen-month construction phase.', $lyceon_json$[{"key":"A","text":"Japan—"},{"key":"B","text":"Japan"},{"key":"C","text":"Japan;"},{"key":"D","text":"Japan:"}]$lyceon_json$::jsonb, 'A', NULL, E'The phrase following the blank ("a project that required relocating over eleven hundred native plant specimens") is an appositive that renames and elaborates on the redesign described in the main clause. An em dash after "Japan" clearly signals the shift to the appositive, providing a strong visual break that separates the geographic parenthetical "Sapporo, Japan" from the explanatory phrase that follows. Omitting all punctuation after "Japan" fuses the geographic name directly into the appositive without any boundary marker, creating a run-on. A semicolon after "Japan" incorrectly treats the appositive as an independent clause, but "a project that required relocating..." lacks a finite verb and is not a complete sentence. A colon after "Japan" is incorrect because a colon must follow an independent clause, and "redesigned the municipal botanical garden in Sapporo, Japan" is not structured as a clause that introduces a list or explanation — the appositive modifies the noun phrase, not the clause.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 115, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2D0XH5F', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'The fruit of the sandbox tree (Hura crepitans), native to tropical regions of Central and South America, disperses its seeds by exploding with a sharp crack that can be heard from over 90 meters away. Each mature fruit capsule splits violently along its segments, launching seeds at speeds measured at up to 70 meters per second — fast enough to embed the seeds into soft bark of neighboring trees. Botanists have noted that virtually no sandbox tree seedlings are found growing within a 15-meter radius of adult trees, while dense clusters of seedlings appear at distances of 30 to 45 meters. This distribution suggests that ________', $lyceon_json$[{"key":"A","text":"the explosive dispersal mechanism effectively propels seeds well beyond the parent tree's canopy shadow, where seedlings face less competition for light and nutrients."},{"key":"B","text":"sandbox tree seeds are unable to germinate unless they are first embedded into the bark of another tree species."},{"key":"C","text":"the explosive mechanism is used primarily to deter herbivores from feeding on the tree's fruit rather than to disperse seeds."},{"key":"D","text":"sandbox trees reproduce mainly through underground root systems rather than through seed germination."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes seeds launched at high velocity and seedlings found at 30 to 45 meters from the parent tree but not within 15 meters. The logical inference is that the explosive mechanism propels seeds beyond the parent''s immediate area, allowing seedlings to establish where they compete less with the adult tree. The option about requiring bark embedding for germination extrapolates from the detail about seeds hitting bark into a germination requirement the passage does not imply. The option about deterring herbivores reinterprets the explosion''s function without textual basis — the passage frames the mechanism as dispersal. The option about root reproduction contradicts the passage''s focus on seed dispersal and seedling distribution as the tree''s reproductive pattern.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2D5TSGI', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Marine biologist Kenji Watanabe has cataloged over three hundred species of deep-sea organisms near hydrothermal vents in the Mariana _____ his research has led to the identification of nine species previously unknown to science.', $lyceon_json$[{"key":"A","text":"Trough. His"},{"key":"B","text":"Trough his"},{"key":"C","text":"Trough, his"},{"key":"D","text":"Trough and his,"}]$lyceon_json$::jsonb, 'A', NULL, E'Two independent clauses flank the blank: the first describes Watanabe''s cataloging work and the second describes the identification of unknown species. A period correctly separates these into two complete sentences. Omitting all punctuation between the clauses produces a fused sentence. Using only a comma creates a comma splice, joining two independent clauses without a coordinating conjunction. Placing a comma after "his" in the phrase "and his," improperly interrupts the second clause''s subject and verb with punctuation that has no grammatical function.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2E32YN1', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which finding, if true, would most directly support Okeke''s hypothesis?', E'Agricultural scientist Chidinma Okeke studied cassava fields in southeastern Nigeria where farmers traditionally intercrop cassava with pigeon pea (Cajanus cajan). She noted that cassava plants grown within 1.5 meters of pigeon pea rows showed significantly lower rates of infection by cassava mosaic virus (CMV) — averaging 9% infection compared to 34% in monoculture plots. Okeke hypothesized that pigeon pea plants harbor large populations of predatory insects, particularly lacewings and ladybird beetles, that feed on whiteflies — the primary vector for CMV transmission. She proposed that these predator populations suppress whitefly numbers near the pigeon pea rows, thereby reducing viral transmission to adjacent cassava plants.', $lyceon_json$[{"key":"A","text":"Whitefly counts on cassava leaves within 1.5 meters of pigeon pea rows averaged 2.3 per plant, compared to 17.6 per plant in monoculture plots, and lacewing densities on nearby pigeon pea foliage were seven times higher than on any other intercrop species tested."},{"key":"B","text":"Pigeon pea plants possess a natural chemical resistance to cassava mosaic virus that prevents viral replication within pigeon pea tissue."},{"key":"C","text":"Farmers in southeastern Nigeria have intercropped cassava and pigeon pea for at least three centuries, according to oral historical accounts collected by ethnobotanists."},{"key":"D","text":"Cassava varieties bred for CMV resistance at the International Institute of Tropical Agriculture showed infection rates below 5% regardless of whether they were intercropped with pigeon pea."}]$lyceon_json$::jsonb, 'A', NULL, E'Okeke''s hypothesis proposes a causal chain: pigeon pea harbors predatory insects that suppress whiteflies, which reduces CMV transmission to nearby cassava. The finding showing dramatically lower whitefly counts near pigeon pea along with much higher lacewing densities on pigeon pea foliage directly supports both links in this chain — predator abundance and vector suppression. The finding about pigeon pea''s chemical resistance to CMV describes a property of the pigeon pea plant itself, not the predator-vector mechanism Okeke proposes. The finding about the historical age of the intercropping practice provides cultural context but does not test the biological mechanism. The finding about resistant cassava varieties concerns a genetic solution independent of intercropping, which would actually undermine the importance of Okeke''s mechanism rather than support it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FQPKQL', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Neither the lead geologist nor the two field assistants who accompanied her on the expedition _____ able to explain the unusual crystalline formations discovered in the lower cavern, which did not match any mineral structure cataloged in the existing geological surveys of the region.', $lyceon_json$[{"key":"A","text":"was"},{"key":"B","text":"were"},{"key":"C","text":"is"},{"key":"D","text":"has been"}]$lyceon_json$::jsonb, 'B', NULL, E'In a "neither...nor" construction, the verb agrees with the subject nearest to it. The nearest subject is "the two field assistants," which is plural, so the verb must be plural. The past tense is established by "accompanied" and "discovered" and "did not match." The plural past-tense "were" correctly agrees with "assistants" and maintains tense consistency. The singular past-tense "was" would agree with "the lead geologist" but not with the nearer subject "assistants," violating the proximity agreement rule. The singular present-tense "is" fails on both number agreement with the nearer plural subject and tense consistency with the past-tense frame. The singular present-perfect "has been" likewise fails number agreement and introduces a tense shift away from the established past narrative.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HUGD0S', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing a brief summary for a class presentation and wants to identify what a specific organism is and explain where it lives. Which choice most effectively uses information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2I7M45D', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the third sentence in the passage ("Vasquez acknowledges . . . the same period")?', E'Musicologist Carmen Vasquez argues that the Cuban danzon evolved not primarily from European contradanza, as the standard account holds, but from a synthesis of Afro-Cuban rhythmic structures that predated sustained European musical contact. She supports this claim by analyzing percussion patterns in danzon recordings from the 1890s that closely mirror ceremonial Lucumi drumming sequences documented by ethnographers a generation earlier. Vasquez acknowledges that European harmonic conventions are unmistakably present in the danzon repertoire but contends that these elements were grafted onto an existing Afro-Cuban rhythmic architecture rather than serving as the foundation from which the genre arose, noting that harmonic borrowing from European sources occurred across many Caribbean genres during the same period.', $lyceon_json$[{"key":"A","text":"It addresses a potential objection to Vasquez's thesis by reframing European musical elements as secondary additions rather than foundational structures"},{"key":"B","text":"It abandons Vasquez's earlier argument and concedes that the standard account of danzon's origins is correct"},{"key":"C","text":"It introduces new percussion evidence that strengthens the claim made in the second sentence"},{"key":"D","text":"It shifts the passage's focus from danzon specifically to Caribbean music genres in general"}]$lyceon_json$::jsonb, 'A', NULL, E'The third sentence concedes the presence of European harmonic elements — a fact that could seem to support the standard contradanza-origin account — but immediately reinterprets them as later additions layered onto a pre-existing Afro-Cuban rhythmic base, thereby neutralizing the objection without weakening the thesis. Abandoning the argument and conceding the standard account misreads the sentence, which explicitly maintains that European elements were secondary grafts rather than the genre''s foundation. Introducing new percussion evidence confuses this sentence with the second; the third sentence discusses harmonic conventions, not drumming patterns, and serves a defensive rather than evidential function. Shifting the focus to Caribbean music generally overstates the mention of other genres, which appears only as a brief supporting detail to show that harmonic borrowing was widespread and therefore not uniquely explanatory of danzon''s origins.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ICS4L5', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'Geochemist Amara Osei-Bonsu analyzed strontium isotope ratios in the tooth enamel of 39 individuals buried at a Bronze Age settlement in northern Ghana. Her findings indicate that 26 of the individuals grew up consuming water from local geological formations, suggesting they were lifelong residents of the settlement. _______ the remaining 13 individuals displayed strontium signatures consistent with granite-derived groundwater found only in a highland region approximately 200 kilometers to the northeast, leading Osei-Bonsu to conclude that those individuals had migrated to the settlement during adolescence or early adulthood.', $lyceon_json$[{"key":"A","text":"Similarly,"},{"key":"B","text":"In other words,"},{"key":"C","text":"However,"},{"key":"D","text":"Therefore,"}]$lyceon_json$::jsonb, 'C', NULL, E'The sentence before the blank establishes that the majority of individuals (26 of 39) were lifelong local residents based on their strontium isotope ratios. The sentence after the blank introduces a contrasting finding about the remaining 13 individuals, whose isotope signatures point to a distant origin. "However," correctly signals that the subsequent information presents a differing or contrasting result to what preceded it. "Similarly," implies the two groups share comparable characteristics, but the passage explicitly distinguishes the migrants from the lifelong residents. "In other words," would restate the preceding claim in different terms, but the subsequent sentence introduces new information about a different subset of individuals. "Therefore," implies the migration conclusion follows as a logical consequence of the 26 individuals being local, but the migration finding is an independent observation about a separate group, not a deduction from the first group''s data.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NJ8EA7', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Based on the text, what does Reinholt''s study primarily demonstrate about the fungi she investigated?', E'Mycologist Astrid Reinholt analyzed the decomposition activity of 41 species of saprotrophic fungi colonizing fallen logs in old-growth beech forests across southern Denmark. She measured the lignin-to-cellulose degradation ratio — the proportion of lignin broken down relative to cellulose — for each species over a 14-month observation period. Reinholt discovered that fungi colonizing logs in direct contact with mineral soil exhibited lignin-to-cellulose ratios averaging 3.1:1, meaning they degraded lignin more than three times as rapidly as cellulose. In contrast, fungi on elevated logs — those suspended above the ground by branches or rocks — showed ratios averaging 0.7:1, degrading cellulose faster than lignin. Reinholt attributed this divergence to differences in nitrogen availability: mineral soil contact provides a steady nitrogen supply, and lignin degradation is a nitrogen-intensive enzymatic process. Without soil nitrogen, the elevated-log fungi apparently shifted their metabolic strategy toward cellulose, which requires less nitrogen to decompose.', $lyceon_json$[{"key":"A","text":"The balance between lignin and cellulose degradation by saprotrophic fungi shifts depending on whether the log contacts mineral soil, likely because soil nitrogen availability influences which decomposition pathway is metabolically favorable."},{"key":"B","text":"Fungi on elevated logs produce no enzymes capable of breaking down lignin, relying entirely on cellulose decomposition for their nutritional needs."},{"key":"C","text":"Southern Danish beech forests have unusually nitrogen-poor soils compared to beech forests in other European regions, which limits fungal decomposition rates."},{"key":"D","text":"Reinholt found that all 41 fungal species she studied were present on both soil-contact and elevated logs in equal abundance."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes how fungi on soil-contact logs degraded lignin far more than cellulose, while fungi on elevated logs showed the reverse pattern, with Reinholt attributing this to nitrogen availability from mineral soil. The option about degradation balance shifting based on soil contact and nitrogen availability accurately summarizes this primary finding. The option about elevated-log fungi producing no lignin-degrading enzymes overstates the finding — the passage says these fungi showed a lower lignin ratio, not zero lignin degradation. The option about unusually nitrogen-poor Danish soils introduces a comparative claim the passage never makes. The option about equal abundance of all species on both log types fabricates data; the passage discusses degradation ratios, not species distribution across log types.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NXKBB5', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Literary scholar Nadira Yusuf has argued that the Somali poet Elmi Boodhari, writing in the 1940s, deliberately employed metrical irregularities to undermine the authority of traditional oral poetic forms, which were closely associated with clan hierarchies he opposed. Yusuf points to 17 poems in which Boodhari breaks from the standard alliterative pattern at moments of explicit political critique, a technique she interprets as a formal enactment of dissent. Some of Yusuf''s colleagues have objected that these irregularities may simply reflect Boodhari''s incomplete training in classical metrics rather than intentional subversion. _______ Yusuf has noted that Boodhari''s non-political poems -- his love lyrics and pastoral descriptions composed during the same period -- adhere flawlessly to the alliterative conventions, a pattern she argues would be inexplicable if the irregularities in his political poems were merely accidental.', $lyceon_json$[{"key":"A","text":"To counter this objection,"},{"key":"B","text":"Along these lines,"},{"key":"C","text":"That is,"},{"key":"D","text":"Regardless,"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence before the blank presents colleagues'' objection that Boodhari''s metrical irregularities might reflect incomplete training rather than intentional subversion. The sentence after the blank presents Yusuf''s rebuttal: his non-political poems follow classical conventions perfectly, which would be inexplicable if his training were the issue. "To counter this objection," correctly signals that what follows is a direct rebuttal to the preceding criticism. "Along these lines," implies that the subsequent sentence extends or agrees with the colleagues'' objection, but it instead opposes their claim. "That is," would restate or clarify the colleagues'' objection in different terms, but the subsequent sentence introduces new evidence (the non-political poems) that contradicts the objection rather than restating it. "Regardless," implies that the subsequent information is presented while setting aside the objection without engaging it, but Yusuf''s evidence directly addresses and refutes the specific claim about incomplete training.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Q12W3W', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Neuroscientist Priya Subramaniam published her findings on synaptic plasticity in patients recovering from traumatic brain _____ the study demonstrated that targeted electrical stimulation could accelerate the formation of new neural pathways by as much as forty-seven percent.', $lyceon_json$[{"key":"A","text":"injuries; however,"},{"key":"B","text":"injuries, however,"},{"key":"C","text":"injuries however,"},{"key":"D","text":"injuries however"}]$lyceon_json$::jsonb, 'A', NULL, E'Two independent clauses flank the blank, connected by the conjunctive adverb "however." A semicolon before "however" correctly joins the clauses, and the comma after "however" properly sets off the conjunctive adverb from the rest of the second clause. Using a comma before "however" creates a comma splice, because a conjunctive adverb does not function as a coordinating conjunction and cannot join independent clauses with only a comma. Omitting punctuation before "however" while retaining the comma after it produces a fused sentence at the clause boundary. Removing all commas around "however" similarly fuses the two clauses and also fails to set off the conjunctive adverb with the required following comma.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RVO4AI', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Historian Kwame Asante examined tax records from 53 market towns in the Ashanti region of present-day Ghana between 1874 and 1896 — the period immediately following British annexation. He found that market towns located on newly constructed colonial roads experienced a 39% increase in the number of registered traders but a 22% decline in the average tax revenue collected per trader. Towns on traditional forest paths that were bypassed by the colonial road network, meanwhile, showed stable trader numbers and stable per-trader tax revenues throughout the same period. Asante observed that the new roads connected Ashanti market towns to large coastal trading posts for the first time, where European firms sold manufactured goods at prices below those of local artisans. This combination of evidence suggests that ________', $lyceon_json$[{"key":"A","text":"colonial roads attracted more traders to roadside market towns but also introduced competition from cheaper coastal goods, which compressed profit margins for individual traders and reduced the taxable income each generated."},{"key":"B","text":"British colonial authorities deliberately set lower tax rates in road-connected towns to encourage trade along the new routes."},{"key":"C","text":"traders in towns on traditional forest paths earned higher incomes than traders in road-connected towns before 1874, which is why their revenues remained stable."},{"key":"D","text":"the 39% increase in registered traders was caused by population growth in the Ashanti region rather than by the construction of colonial roads."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents three connected observations: road-connected towns gained traders but lost per-trader tax revenue, bypassed towns stayed stable, and the roads linked markets to coastal posts selling cheap European goods. The logical completion is that roads attracted more traders but exposed them to coastal competition, compressing individual profits and reducing per-trader taxable income. The option about deliberately lower tax rates introduces a policy action the passage never mentions — the passage discusses revenue per trader, not tax rates set by authorities. The option about pre-1874 income levels in forest-path towns introduces a comparison to a period before the study''s timeframe that the passage does not address. The option attributing trader increases to population growth ignores the passage''s emphasis on roads as the distinguishing variable, since bypassed towns showed no trader increase despite being in the same region.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RWF9U2', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the main idea of the text?', E'Paleoclimatologist Renata Vasquez has challenged the prevailing explanation for the abrupt 1.7-degree Celsius warming event recorded in Greenland ice cores approximately 11,700 years ago, which marks the end of the Younger Dryas cold period. The standard model attributes this rapid warming to a sudden resumption of the Atlantic Meridional Overturning Circulation (AMOC), a deep-ocean current system that transports tropical heat northward. Vasquez''s analysis of beryllium-10 concentrations in Antarctic ice cores from the same period, however, reveals a sharp decline in cosmogenic isotope production beginning approximately 60 years before the warming signal appears in Greenland. Since beryllium-10 production is modulated by solar magnetic field strength — stronger fields deflect more cosmic rays, reducing isotope production — this 60-year lead suggests that a sustained increase in solar output may have initiated the warming, with the AMOC resumption occurring as a secondary response to solar-driven ice sheet retreat rather than as the primary trigger. If correct, Vasquez''s resequencing would subordinate ocean circulation to solar forcing in the causal chain, though she acknowledges that the 60-year offset falls within the dating uncertainty of the Antarctic cores and requires independent confirmation.', $lyceon_json$[{"key":"A","text":"Vasquez argues that a sustained solar output increase may have triggered the end of the Younger Dryas, with ocean circulation changes following as a secondary effect, though the evidence depends on a chronological offset that remains within dating uncertainty."},{"key":"B","text":"Vasquez has conclusively disproven the AMOC model by demonstrating that beryllium-10 levels in Antarctic ice cores are unrelated to solar magnetic field activity."},{"key":"C","text":"The 1.7-degree warming event at the end of the Younger Dryas occurred simultaneously in both hemispheres, which is inconsistent with an ocean-circulation explanation."},{"key":"D","text":"Beryllium-10 is produced exclusively in Antarctic ice and therefore cannot be used to make inferences about Northern Hemisphere climate events."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents Vasquez''s argument that beryllium-10 data suggest solar forcing preceded the Younger Dryas warming by about 60 years, potentially making AMOC resumption a secondary response rather than the primary cause, while noting the dating uncertainty. The option capturing this argument with its caveat accurately reflects the main idea. The option about conclusive disproof misrepresents the passage — Vasquez acknowledges the offset falls within dating uncertainty and needs confirmation, falling short of definitive proof. The option about simultaneous hemispheric warming introduces a claim the passage does not make; the text discusses Antarctic isotope data and Greenland temperature data, not simultaneous warming in both hemispheres. The option about beryllium-10 being exclusively Antarctic is factually wrong within the passage''s own framework — beryllium-10 is a cosmogenic isotope produced in the atmosphere, and the passage uses Antarctic cores as a measurement source, not as the only place it exists.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SLX9JU', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is writing a comparative essay and wants to emphasize that two independent studies, despite investigating different sensory modalities, converge on the same underlying neurological mechanism. Which choice most effectively uses information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2T2E1LD', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the passages, how would Nkomo most likely respond to Park''s recommendation?', E'Text 1
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TIR0TC', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the passage, "prosecute" most nearly means', E'Maritime archaeologist Tomoko Ishida spent fourteen years attempting to prosecute a comprehensive survey of shipwrecks along the Tsugaru Strait, a project repeatedly delayed by political disputes over salvage jurisdiction, equipment shortages, and a three-year funding freeze imposed by the prefecture''s cultural affairs bureau following a 2011 audit.', $lyceon_json$[{"key":"A","text":"indict"},{"key":"B","text":"carry out"},{"key":"C","text":"litigate"},{"key":"D","text":"abandon"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage describes Ishida''s prolonged effort to conduct a comprehensive survey, with multiple obstacles delaying the work. "Carry out" correctly captures this sense of pursuing and executing a sustained undertaking. "Indict" means to formally charge someone with a crime through a legal proceeding, which is incoherent when applied to conducting an archaeological survey of shipwrecks. "Litigate" means to take a legal dispute through the court system, which has no logical connection to performing a maritime field study. "Abandon" means to give up or cease an activity entirely, which directly contradicts the passage''s indication that Ishida spent fourteen years attempting to complete the project despite setbacks.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2UUP4ER', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'As used in the passage, "sustained" most nearly means', E'The greenhouse experiment required the botanist to provide sustained humidity levels above eighty-five percent for eleven consecutive weeks, a condition she maintained by installing a misting system that cycled every forty-seven minutes throughout the growth chamber.', $lyceon_json$[{"key":"A","text":"endured"},{"key":"B","text":"continuous"},{"key":"C","text":"injured"},{"key":"D","text":"audible"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage describes humidity levels that had to be kept constant over an extended period, with a misting system running on a regular cycle to maintain them. "Continuous" correctly captures this sense of something maintained without interruption over time. "Endured" means to suffer through hardship or pain, which is incoherent when applied to humidity levels in a greenhouse — humidity levels do not experience suffering. "Injured" means to cause physical harm or damage to something, which has no logical connection to the maintenance of a climate condition. "Audible" means capable of being heard, which is entirely unrelated to a measurement of atmospheric moisture.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VPG6SS', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'A team of marine biologists at the University of Bergen reported in 2023 that populations of the deep-sea sponge Geodia barretti along the Norwegian continental shelf have been filtering microplastic particles from the surrounding water column at unexpectedly high rates. By deploying sediment traps around 83 individual sponges at depths between 290 and 530 meters, the researchers measured that each sponge retained an average of 1,700 microplastic fragments per day in its internal tissue. The sponges did not appear to digest or break down the plastic; instead, the particles accumulated in dense clusters within the sponges'' mesohyl — the gelatinous matrix that forms their structural core. The researchers noted that while this filtering removes microplastics from the water, it may pose long-term risks to the sponges themselves by disrupting nutrient transport within the mesohyl.', $lyceon_json$[{"key":"A","text":"Deep-sea sponges along the Norwegian shelf are accumulating microplastics in their internal tissue at high rates, which removes plastic from the water but may ultimately harm the sponges."},{"key":"B","text":"Geodia barretti is the only marine organism capable of filtering microplastic particles from deep ocean water."},{"key":"C","text":"The University of Bergen has developed a method to use deep-sea sponges commercially for microplastic removal in polluted harbors."},{"key":"D","text":"Microplastic pollution in the Norwegian continental shelf has decreased significantly since 2023 because of natural sponge filtration."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes how deep-sea sponges filter and retain large quantities of microplastics in their mesohyl, noting both the environmental benefit of removing plastic from the water and the potential risk to the sponges from accumulated particles. The option about accumulation removing plastic but potentially harming sponges captures this dual finding. The option claiming Geodia barretti is the only organism capable of filtering microplastics overgeneralizes far beyond what the passage states. The option about commercial deployment invents a practical application the passage never mentions. The option about decreased pollution levels introduces an outcome the passage does not describe — the researchers documented sponge behavior, not a measurable reduction in overall microplastic levels.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XTNBFM', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which quotation from the study, if accurate, would most directly support the researchers'' conclusion about the owls'' hunting strategy?', E'Ornithologists at the University of Oulu in Finland observed that Tengmalm''s owls (Aegolius funereus) in boreal forests near Kuusamo adjusted their hunting behavior based on snow depth. When snow cover exceeded 37 centimeters, the owls shifted from their typical strategy of listening for voles beneath the snow and plunging through the surface to instead hunting along plowed forest roads and cleared logging tracks where snow was compacted or absent. The researchers concluded that the owls switch to road-hunting because deep, loose snow makes plunge-hunting energetically prohibitive — the owls cannot reliably penetrate thick snow to reach prey below.', $lyceon_json$[{"key":"A","text":"\"Owls tracked via GPS transmitters spent 81% of their nocturnal hunting time within 9 meters of plowed roads when surrounding snow depth exceeded 37 centimeters, but only 12% of hunting time near roads when snow was below 20 centimeters.\""},{"key":"B","text":"\"Tengmalm's owls in Kuusamo consumed an average of 3.4 voles per night, a figure consistent with energy expenditure models for boreal raptors of similar body mass.\""},{"key":"C","text":"\"The plowed forest roads near Kuusamo were maintained by the Finnish Forest Administration and were cleared of snow approximately every 72 hours during winter months.\""},{"key":"D","text":"\"Tengmalm's owls are one of seventeen owl species found in Finnish boreal forests, though they are among the least commonly observed due to their strictly nocturnal habits.\""}]$lyceon_json$::jsonb, 'A', NULL, E'The researchers'' conclusion is that deep snow causes owls to shift from plunge-hunting in open forest to hunting near plowed roads. The quotation showing that GPS-tracked owls spent 81% of hunting time near roads when snow was deep but only 12% when snow was shallow directly demonstrates this behavioral shift in response to snow depth. The quotation about vole consumption rates describes dietary quantity without addressing how snow depth affects hunting location. The quotation about road maintenance frequency provides background on the roads themselves but does not connect snow conditions to owl behavior. The quotation about species diversity and observability in Finnish forests offers ecological context but is unrelated to the specific claim about snow-driven hunting shifts.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
